    std::cout << '\n';
}

int main() {
    std::vector<int> nums = {10, 21, 32, 43, 54, 65};
    nums.insert(nums.begin(), 99);
    print(nums);
    nums.insert(nums.begin() + 2, 99);
    print(nums);
    nums.erase(nums.end() - 1);
    print(nums);
    nums.erase(nums.end() - 2, nums.end());
    print(nums);

    for (auto it = nums.begin(); it != nums.end();) {
        if (*it % 2 == 0) {
            it = nums.erase(it);
        } else {
            ++it;
        }
    }
    print(nums);
    return 0;
}

steps.body:
`std::find` checks every element: O(n). On **sorted** data, the binary searches in `<algorithm>` halve the range at each step and need only O(log n) comparisons, about 20 for a million elements.

- `std::binary_search(first, last, x)` returns a `bool`: is `x` there?
- `std::lower_bound(first, last, x)` returns an iterator to the first element `>= x`. That is where `x` is, or where it would be inserted to keep the order.
- `std::upper_bound(first, last, x)` returns an iterator to the first element `> x`.

Subtract `begin()` to get an index. `lower_bound` returns `end()` when every element is smaller than `x`, and `upper_bound` does when no element is larger, so check before reading `*it`. Everything from `lower_bound` up to (not including) `upper_bound` equals `x`, so their difference counts the copies:

```cpp harness
#include <bits/stdc++.h>

int main() {
    const std::vector<int> v = {1, 3, 3, 3, 7, 9};
    {{code}}
    std::cout << "count of 3: " << count << '\n';
    return 0;
}
```

```cpp
auto count = std::upper_bound(v.begin(), v.end(), 3)
           - std::lower_bound(v.begin(), v.end(), 3);
```

To find `x` and its position at once, use `lower_bound` and test `it != v.end() && *it == x`.

> Gotcha: the data must be sorted first, usually with `std::sort`. On unsorted data these functions do not fail loudly. They just return wrong answers.

example.code:
#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    const std::vector<int> nums = {1, 3, 3, 3, 7, 9};  // already sorted
    std::cout << std::boolalpha;
    std::cout << "has 7: " << std::binary_search(nums.begin(), nums.end(), 7) << '\n';
    std::cout << "has 4: " << std::binary_search(nums.begin(), nums.end(), 4) << '\n';

    auto low3 = std::lower_bound(nums.begin(), nums.end(), 3);
    auto low4 = std::lower_bound(nums.begin(), nums.end(), 4);
    auto high3 = std::upper_bound(nums.begin(), nums.end(), 3);
    std::cout << "lower_bound(3): " << (low3 - nums.begin()) << '\n';
    std::cout << "lower_bound(4): " << (low4 - nums.begin()) << '\n';
    std::cout << "upper_bound(3): " << (high3 - nums.begin()) << '\n';
    std::cout << "count of 3: " << (high3 - low3) << '\n';
    return 0;
}

