#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<int> scores = {80, 65, 90, 80, 72, 80};
    std::sort(scores.begin(), scores.end());

    std::cout << std::boolalpha;
    std::cout << "has 90: " << std::binary_search(scores.begin(), scores.end(), 90) << '\n';
    std::cout << "has 85: " << std::binary_search(scores.begin(), scores.end(), 85) << '\n';

    auto spot = std::lower_bound(scores.begin(), scores.end(), 75);
    std::cout << "insert 75 at: " << (spot - scores.begin()) << '\n';

    auto low = std::lower_bound(scores.begin(), scores.end(), 80);
    auto high = std::upper_bound(scores.begin(), scores.end(), 80);
    std::cout << "count of 80: " << (high - low) << '\n';
    return 0;
}
